import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type * as Three from "three";
import "./RealismViewer.css";

// 3D viewer for the Realism Skyscrapers puzzle. Coordinates match the
// solution's 9x9 <PuzzleGrid>s: the grid proper is rows/cols 1..N and the
// observers sit in the surrounding ring (row/col 0 or N+1). `text` takes the
// same "|"-separated format (ring ignored, "." = empty), and `view`, `selected`
// and the keys of `clues` are "r,c" strings like the grids' renderCell keys.

type Pos = [number, number];

const EYE = 0.15; // eye height, in stories
const MAX_FOV = 110; // vertical, in degrees; the viewer starts fully zoomed out
// Looking up by this much frames a height-7 building right in front of you
// (0.5 away) with roughly equal margins above and below at MAX_FOV.
const START_PITCH = 0.6;

const parsePos = (s: string): Pos => s.split(",").map(Number) as Pos;
const posKey = ([r, c]: Pos) => `${r},${c}`;

const parseHeights = (text: string): number[][] => {
  const rows = text.split("|").slice(1, -1);
  return rows.map((row) =>
    [...row.slice(1, -1)].map((ch) => {
      const h = parseInt(ch, 10);
      return h >= 1 && h <= rows.length ? h : 0;
    })
  );
};

const hueOf = (h: number, n: number) => (h - 1) / n;

// world x (from a column) or z (from a row), with the grid centered on 0
const coord = (i: number, n: number) => i - (n + 1) / 2;

// yaw 0 looks toward -z; face into the grid
const yawFacingIn = ([r, c]: Pos, n: number) =>
  r === 0 ? Math.PI : r === n + 1 ? 0 : c === 0 ? -Math.PI / 2 : Math.PI / 2;

type Engine = {
  THREE: typeof Three;
  scene: Three.Scene;
  camera: Three.PerspectiveCamera;
  buildings: Three.Group;
  pastel: Three.Material[];
  red: Three.Material;
  boxGeo: Three.BoxGeometry;
  render: () => void;
};

export function RealismViewer({
  text,
  size = 7,
  view: initialView = "0,4",
  selected: initialSelected,
  clues = {},
  solution,
}: {
  text?: string;
  size?: number;
  view?: string;
  selected?: string;
  clues?: Record<string, string | number>;
  // passed from the MDX rather than hardcoded, so it isn't in the client bundle
  solution?: string;
}) {
  const [heights, setHeights] = useState(() =>
    text
      ? parseHeights(text)
      : Array.from({ length: size }, () => Array<number>(size).fill(0))
  );
  const n = heights.length;
  const [view, setView] = useState(() => parsePos(initialView));
  const [selected, setSelected] = useState<Pos | null>(() =>
    initialSelected ? parsePos(initialSelected) : null
  );

  // state rather than a ref so the 3D view is rebuilt when the canvas moves
  // between the page and the popped-out window
  const [canvas, setCanvas] = useState<HTMLCanvasElement | null>(null);
  const inputsRef = useRef<Record<string, HTMLInputElement | null>>({});
  // kept outside the engine so they survive popping in/out
  const viewRef = useRef(view);
  const lookRef = useRef({ yaw: 0, pitch: 0, fov: MAX_FOV });
  const [engine, setEngine] = useState<Engine | null>(null);
  const [popup, setPopup] = useState<Window | null>(null);

  // three.js is big, so only load it when a viewer is actually on the page
  useEffect(() => {
    if (!canvas) return;
    const win = canvas.ownerDocument.defaultView ?? window;
    let cleanup: (() => void) | undefined;
    let cancelled = false;
    void import("three").then((THREE) => {
      if (cancelled) return;
      const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
      const scene = new THREE.Scene();
      scene.background = new THREE.Color(0xdde3ea);
      const camera = new THREE.PerspectiveCamera(
        lookRef.current.fov,
        4 / 3,
        0.01,
        100
      );
      camera.rotation.order = "YXZ";

      scene.add(new THREE.AmbientLight(0xffffff, 1.7));
      const sun = new THREE.DirectionalLight(0xffffff, 1.9);
      sun.position.set(3, 10, 5);
      scene.add(sun);

      const ground = new THREE.Mesh(
        new THREE.PlaneGeometry(60, 60),
        new THREE.MeshLambertMaterial({ color: 0xb8b8b0 })
      );
      ground.rotation.x = -Math.PI / 2;
      scene.add(ground);
      const lines = new THREE.GridHelper(n, n, 0x888888, 0x888888);
      lines.position.y = 0.001;
      scene.add(lines);

      const buildings = new THREE.Group();
      scene.add(buildings);

      const render = () => {
        const w = canvas.clientWidth;
        const h = canvas.clientHeight;
        const dpr = win.devicePixelRatio;
        if (
          canvas.width !== Math.round(w * dpr) ||
          canvas.height !== Math.round(h * dpr)
        ) {
          renderer.setPixelRatio(dpr);
          renderer.setSize(w, h, false);
          camera.aspect = w / h;
          camera.updateProjectionMatrix();
        }
        const [r, c] = viewRef.current;
        camera.position.set(coord(c, n), EYE, coord(r, n));
        camera.rotation.set(lookRef.current.pitch, lookRef.current.yaw, 0);
        renderer.render(scene, camera);
      };

      const onWheel = (e: WheelEvent) => {
        e.preventDefault();
        camera.fov = lookRef.current.fov = Math.max(
          20,
          Math.min(MAX_FOV, camera.fov + e.deltaY * 0.05)
        );
        camera.updateProjectionMatrix();
        render();
      };
      // removed in cleanup below; React's onWheel is passive so can't preventDefault
      // eslint-disable-next-line @eslint-react/web-api-no-leaked-event-listener
      canvas.addEventListener("wheel", onWheel, { passive: false });
      const resizeObserver = new win.ResizeObserver(render);
      resizeObserver.observe(canvas);

      const pastel = Array.from(
        { length: n + 1 },
        (_, h) =>
          new THREE.MeshLambertMaterial({
            color: new THREE.Color().setHSL(hueOf(h, n), 0.45, 0.8),
          })
      );
      const red = new THREE.MeshLambertMaterial({ color: 0xdd2222 });
      const boxGeo = new THREE.BoxGeometry(1, 1, 1);

      setEngine({
        THREE,
        scene,
        camera,
        buildings,
        pastel,
        red,
        boxGeo,
        render,
      });
      cleanup = () => {
        canvas.removeEventListener("wheel", onWheel);
        resizeObserver.disconnect();
        scene.traverse((obj) => {
          if (obj instanceof THREE.Mesh || obj instanceof THREE.LineSegments) {
            (obj.geometry as Three.BufferGeometry).dispose();
            (obj.material as Three.Material).dispose();
          }
        });
        pastel.forEach((m) => m.dispose());
        red.dispose();
        boxGeo.dispose();
        renderer.dispose();
      };
    });
    return () => {
      cancelled = true;
      cleanup?.();
      setEngine(null);
    };
  }, [canvas, n]);

  useEffect(() => {
    if (!engine) return;
    const { THREE, buildings, pastel, red, boxGeo } = engine;
    buildings.clear();
    heights.forEach((row, i) =>
      row.forEach((h, j) => {
        if (!h) return;
        const isSel = selected?.[0] === i + 1 && selected[1] === j + 1;
        const m = new THREE.Mesh(boxGeo, isSel ? red : pastel[h]);
        m.scale.y = h;
        m.position.set(coord(j + 1, n), h / 2, coord(i + 1, n));
        buildings.add(m);
      })
    );
    engine.render();
  }, [engine, heights, selected, n]);

  useEffect(() => {
    viewRef.current = view;
    lookRef.current = {
      ...lookRef.current,
      yaw: yawFacingIn(view, n),
      pitch: START_PITCH,
    };
  }, [view, n]);

  useEffect(() => {
    engine?.render();
  }, [engine, view]);

  const openPopup = () => {
    const win = window.open("", "", "popup,width=560,height=800");
    if (!win) return;
    win.document.title = "Realism visualizer";
    // the site's styles (and theme classes) so the viewer looks the same
    win.document.head.replaceChildren(
      ...[
        ...document.head.querySelectorAll('style, link[rel="stylesheet"]'),
      ].map((el) => {
        const copy = el.cloneNode(true);
        // relative hrefs won't resolve from the blank popup
        if (el instanceof HTMLLinkElement)
          (copy as HTMLLinkElement).href = el.href;
        return copy;
      })
    );
    win.document.documentElement.className = document.documentElement.className;
    win.document.body.className = "realism-viewer-window";
    setPopup(win);
  };

  useEffect(() => {
    if (!popup) return;
    const onClose = () => setPopup(null);
    popup.addEventListener("pagehide", onClose);
    return () => {
      popup.removeEventListener("pagehide", onClose);
      popup.close();
    };
  }, [popup]);

  const dragRef = useRef<{ x: number; y: number } | null>(null);

  const setHeight = (r: number, c: number, h: number) =>
    setHeights((prev) =>
      prev.map((row, i) =>
        i === r - 1
          ? row.map((old, j) =>
              j === c - 1 ? (h >= 1 && h <= n ? h : 0) : old
            )
          : row
      )
    );

  const onCellKeyDown = (
    e: React.KeyboardEvent<HTMLInputElement>,
    r: number,
    c: number
  ) => {
    const moves: Record<string, Pos> = {
      ArrowUp: [-1, 0],
      ArrowDown: [1, 0],
      ArrowLeft: [0, -1],
      ArrowRight: [0, 1],
    };
    if (e.key in moves) {
      const [dr, dc] = moves[e.key];
      const nr = Math.max(1, Math.min(n, r + dr));
      const nc = Math.max(1, Math.min(n, c + dc));
      inputsRef.current[posKey([nr, nc])]?.focus();
    } else if (/^[0-9]$/.test(e.key)) setHeight(r, c, +e.key);
    else if (e.key === "Backspace" || e.key === "Delete") setHeight(r, c, 0);
    else if (e.key === "Escape") {
      setSelected(null);
      e.currentTarget.blur();
    } else if (e.key === "Tab" || e.metaKey || e.ctrlKey) return;
    e.preventDefault();
  };

  const range = Array.from({ length: n + 2 }, (_, i) => i);

  const box = (
    <div className="realism-viewer">
      <p className="realism-viewer-instructions">
        Cells are editable. Selecting a cell highlights its building in red.
        Click a position around the edge to view from there. The 3D view can be
        dragged and scrolled.
      </p>
      <div className="realism-viewer-controls">
        {solution && (
          <button
            type="button"
            onClick={() => setHeights(parseHeights(solution))}
          >
            Load solution
          </button>
        )}
        <button
          type="button"
          onClick={() => {
            setHeights((prev) => prev.map((row) => row.map(() => 0)));
            setSelected(null);
          }}
        >
          Clear
        </button>
        {popup ? (
          <button type="button" onClick={() => setPopup(null)}>
            Dock
          </button>
        ) : (
          <button type="button" onClick={openPopup}>
            Pop out
          </button>
        )}
      </div>
      <div className="realism-viewer-body">
        <table className="realism-viewer-grid">
          <tbody>
            {range.map((r) => (
              <tr key={r}>
                {range.map((c) => {
                  const inside = r >= 1 && r <= n && c >= 1 && c <= n;
                  const ring =
                    !inside && (r >= 1 && r <= n) !== (c >= 1 && c <= n);
                  const key = posKey([r, c]);
                  if (inside) {
                    const h = heights[r - 1][c - 1];
                    const isSel = selected?.[0] === r && selected[1] === c;
                    return (
                      <td key={c} className="realism-viewer-cell">
                        <input
                          ref={(el) => {
                            inputsRef.current[key] = el;
                          }}
                          className={isSel ? "sel" : undefined}
                          style={
                            h
                              ? {
                                  backgroundColor: `hsl(${hueOf(h, n) * 360}, 45%, 92%)`,
                                  color: "black",
                                }
                              : undefined
                          }
                          inputMode="numeric"
                          value={h || ""}
                          onKeyDown={(e) => onCellKeyDown(e, r, c)}
                          // fallback for on-screen keyboards that don't send keydown digits
                          onChange={(e) =>
                            setHeight(
                              r,
                              c,
                              parseInt(e.target.value.slice(-1), 10)
                            )
                          }
                          onFocus={() => setSelected([r, c])}
                        />
                      </td>
                    );
                  }
                  if (ring) {
                    const isView = view[0] === r && view[1] === c;
                    return (
                      <td key={c}>
                        <button
                          type="button"
                          className={isView ? "sel" : undefined}
                          title="View from here"
                          onClick={() => setView([r, c])}
                        >
                          {clues[key]}
                        </button>
                      </td>
                    );
                  }
                  return <td key={c} />;
                })}
              </tr>
            ))}
          </tbody>
        </table>
        <canvas
          ref={setCanvas}
          className="realism-viewer-canvas"
          onPointerDown={(e) => {
            dragRef.current = { x: e.clientX, y: e.clientY };
            e.currentTarget.setPointerCapture(e.pointerId);
          }}
          onPointerMove={(e) => {
            if (!dragRef.current || !engine) return;
            const k =
              ((lookRef.current.fov / e.currentTarget.clientHeight) * Math.PI) /
              180;
            lookRef.current.yaw += (e.clientX - dragRef.current.x) * k;
            lookRef.current.pitch = Math.max(
              -1.5,
              Math.min(
                1.5,
                lookRef.current.pitch + (e.clientY - dragRef.current.y) * k
              )
            );
            dragRef.current = { x: e.clientX, y: e.clientY };
            engine.render();
          }}
          onPointerUp={() => {
            dragRef.current = null;
          }}
        />
      </div>
    </div>
  );

  if (!popup) return box;
  return (
    <>
      <div className="realism-viewer-placeholder">
        The visualizer is open in a separate window.{" "}
        <button type="button" onClick={() => setPopup(null)}>
          Dock
        </button>
      </div>
      {createPortal(box, popup.document.body)}
    </>
  );
}
